package com.gymmind.course.api;
import com.gymmind.course.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestController @RequestMapping("/api/v1/courses") @SecurityRequirement(name="bearerAuth") public class CourseController{private final CourseService service; private final CurrentActorProvider actors; public CourseController(CourseService s,CurrentActorProvider a){service=s;actors=a;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<CourseView> create(@Valid @RequestBody CreateRequest r){return ApiResponse.success(service.create(actors.requireCurrent(),new CreateCourseCommand(null,r.coachId(),r.title(),r.type(),r.startsAt(),r.endsAt(),r.capacity(),r.location())));} @PatchMapping("/{id}") public ApiResponse<Void> update(@PathVariable Long id,@Valid @RequestBody UpdateRequest r){service.update(actors.requireCurrent(),id,r.title(),r.type(),r.startsAt(),r.endsAt(),r.capacity(),r.location());return ApiResponse.success(null);} @PostMapping("/{id}/cancel") public ApiResponse<Void> cancel(@PathVariable Long id){service.cancel(actors.requireCurrent(),id);return ApiResponse.success(null);} public record CreateRequest(Long coachId,@NotBlank String title,@NotBlank String type,Instant startsAt,Instant endsAt,int capacity,@NotBlank String location){} public record UpdateRequest(@NotBlank String title,@NotBlank String type,Instant startsAt,Instant endsAt,int capacity,@NotBlank String location){} }
